// Writes js/woodcut/gen/r3a-lyrics.js for looks/woodcut-r3a.html (round 3, agent wood-A: stanzas 6-7) from
// source/lines.json. Lines 31-40 (stanza 5) come along only so the seam page (page 28) can be set exactly as
// looks/woodcut.html sets it. Run from the project folder:   node js/woodcut/r3a-make-lyrics.mjs
// The output quotes the lyric, so it lives under gen/ (gitignored). Never edit the generated file by hand.
import fs from 'fs';
const d = JSON.parse(fs.readFileSync('source/lines.json', 'utf8'));
const lines = d.lines.filter(l => l.i >= 31 && l.i <= 64).map(l => ({ i: l.i, text: l.text, s: l.s, e: l.e, words: l.words.map(w => ({ w: w.w, s: w.s, e: w.e })) }));
lines.forEach((l, k) => { if (l.i !== 31 + k) throw new Error('line index ' + l.i + ' at ' + k); });
for (const l of lines) if (l.words.map(w => w.w).join(' ') !== l.text) throw new Error('word list does not rebuild line ' + l.i);
fs.mkdirSync('js/woodcut/gen', { recursive: true });
fs.writeFileSync('js/woodcut/gen/r3a-lyrics.js', '// GENERATED by r3a-make-lyrics.mjs from source/lines.json (' + d.sha256.slice(0, 12) + '). Do not edit.\nconst R3A_LY = ' + JSON.stringify(lines) + ';\n');
console.log(lines.length, 'lines', lines[0].i, '-', lines[lines.length - 1].i);
